// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

library ActiveOfferLib {
    /**
     * @notice Remove an offerId from an active list (swap & pop)
     */
    function remove(uint256[] storage list, uint256 offerId) internal {
        uint256 length = list.length;

        for (uint256 i = 0; i < length; i++) {
            if (list[i] == offerId) {
                list[i] = list[length - 1];
                list.pop();
                return;
            }
        }
    }
}

contracts/interfaces/CollateralManager.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "./PriceOracle.sol";

/**
 * @title CollateralManager
 * @notice Manages collateral deposits, withdrawals, and liquidations for lending platform
 * @dev Integrates with PriceOracle for real-time collateral valuation
 */
contract CollateralManager is AccessControl, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ============ State Variables ============

    bytes32 public constant LENDING_POOL_ROLE = keccak256("LENDING_POOL_ROLE");
    bytes32 public constant LIQUIDATOR_ROLE = keccak256("LIQUIDATOR_ROLE");

    PriceOracle public immutable priceOracle;

    // Collateral deposits
    mapping(uint256 => CollateralDeposit) public deposits;
    mapping(uint256 => uint256[]) public loanToDepositIds; // loanId => depositIds[]
    mapping(address => uint256[]) public userDepositIds; // user => depositIds[]

    // Token information
    mapping(address => TokenInfo) public supportedTokens;
    mapping(address => uint8) public tokenDecimals;
    address[] public supportedTokenList;

    // Counters
    uint256 public nextDepositId;

    // Liquidation parameters
    uint256 public constant LIQUIDATION_THRESHOLD = 11000; // 110% (in basis points)
    uint256 public constant MIN_COLLATERAL_RATIO = 12000; // 120% (in basis points)
    uint256 public constant LIQUIDATION_BONUS = 500; // 5% bonus for liquidators
    uint256 public constant BASIS_POINTS = 10000; // 100%

    // Grace period before liquidation (to give borrower time to add collateral)
    uint256 public constant LIQUIDATION_GRACE_PERIOD = 1 hours;

    // ============ Structs ============

    struct CollateralDeposit {
        uint256 depositId;
        address depositor;
        address tokenAddress;
        uint256 amount;
        uint256 loanId;
        bool isLocked;
        uint256 depositTimestamp;
        uint256 lockedTimestamp;
    }

    struct TokenInfo {
        bool isSupported;
        uint256 maxDepositAmount; // Max amount that can be deposited
        uint256 liquidationPenalty; // Penalty on liquidation (basis points)
        uint256 totalDeposited; // Total amount currently deposited
    }

    struct CollateralValue {
        address tokenAddress;
        uint256 amount;
        uint256 valueInUSD;
        uint256 lastUpdated;
    }

    // ============ Events ============

    event CollateralDeposited(
        uint256 indexed depositId,
        address indexed depositor,
        uint256 indexed loanId,
        address tokenAddress,
        uint256 amount,
        uint256 timestamp
    );

    event CollateralWithdrawn(
        uint256 indexed depositId,
        address indexed depositor,
        address tokenAddress,
        uint256 amount
    );

    event CollateralLocked(
        uint256 indexed depositId,
        uint256 indexed loanId,
        address tokenAddress,
        uint256 amount,
        uint256 timestamp
    );

    event CollateralUnlocked(
        uint256 indexed depositId,
        uint256 indexed loanId,
        address tokenAddress,
        uint256 amount
    );

    event CollateralLiquidated(
        uint256 indexed depositId,
        uint256 indexed loanId,
        address indexed borrower,
        address liquidator,
        address tokenAddress,
        uint256 amount,
        uint256 recoveredValue
    );

    event TokenAdded(
        address indexed token,
        uint256 maxDepositAmount,
        uint256 liquidationPenalty
    );

    event TokenRemoved(address indexed token);

    event TokenConfigUpdated(
        address indexed token,
        uint256 maxDepositAmount,
        uint256 liquidationPenalty
    );

    // ============ Errors ============

    error CollateralManager__InvalidToken();
    error CollateralManager__TokenNotSupported();
    error CollateralManager__InvalidAmount();
    error CollateralManager__DepositNotFound();
    error CollateralManager__DepositLocked();
    error CollateralManager__DepositNotLocked();
    error CollateralManager__UnauthorizedWithdrawal();
    error CollateralManager__InsufficientCollateral();
    error CollateralManager__CannotLiquidate();
    error CollateralManager__ZeroAddress();
    error CollateralManager__MaxDepositExceeded();
    error CollateralManager__TransferFailed();
    error CollateralManager__GracePeriodActive();

    // ============ Constructor ============

    constructor(address _priceOracle) {
        if (_priceOracle == address(0)) revert CollateralManager__ZeroAddress();

        priceOracle = PriceOracle(_priceOracle);

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(LIQUIDATOR_ROLE, msg.sender);

        nextDepositId = 1;
    }

    // ============ External Functions ============

    /**
     * @notice Add a supported collateral token
     * @param token The token address
     * @param decimals_ The token decimals
     * @param maxDepositAmount Maximum deposit amount
     * @param liquidationPenalty Liquidation penalty in basis points
     */
    function addSupportedToken(
        address token,
        uint8 decimals_,
        uint256 maxDepositAmount,
        uint256 liquidationPenalty
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (token == address(0)) revert CollateralManager__ZeroAddress();
        if (supportedTokens[token].isSupported)
            revert CollateralManager__InvalidToken();

        // Verify token is supported by price oracle
        if (!priceOracle.isSupportedToken(token)) {
            revert CollateralManager__TokenNotSupported();
        }

        supportedTokens[token] = TokenInfo({
            isSupported: true,
            maxDepositAmount: maxDepositAmount,
            liquidationPenalty: liquidationPenalty,
            totalDeposited: 0
        });

        tokenDecimals[token] = decimals_;
        supportedTokenList.push(token);

        emit TokenAdded(token, maxDepositAmount, liquidationPenalty);
    }

    /**
     * @notice Remove a supported token
     * @param token The token address
     */
    function removeSupportedToken(
        address token
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (!supportedTokens[token].isSupported) {
            revert CollateralManager__TokenNotSupported();
        }

        // Check no active deposits
        if (supportedTokens[token].totalDeposited > 0) {
            revert CollateralManager__InvalidToken();
        }

        supportedTokens[token].isSupported = false;

        // Remove from list
        for (uint256 i = 0; i < supportedTokenList.length; i++) {
            if (supportedTokenList[i] == token) {
                supportedTokenList[i] = supportedTokenList[
                    supportedTokenList.length - 1
                ];
                supportedTokenList.pop();
                break;
            }
        }

        emit TokenRemoved(token);
    }

    /**
     * @notice Update token configuration
     * @param token The token address
     * @param maxDepositAmount New max deposit amount
     * @param liquidationPenalty New liquidation penalty
     */
    function updateTokenConfig(
        address token,
        uint256 maxDepositAmount,
        uint256 liquidationPenalty
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (!supportedTokens[token].isSupported) {
            revert CollateralManager__TokenNotSupported();
        }

        supportedTokens[token].maxDepositAmount = maxDepositAmount;
        supportedTokens[token].liquidationPenalty = liquidationPenalty;

        emit TokenConfigUpdated(token, maxDepositAmount, liquidationPenalty);
    }

    /**
     * @notice Deposit collateral for a loan
     * @param loanId The ID of the loan
     * @param tokenAddress The address of the collateral token
     * @param amount The amount to deposit
     * @return depositId The ID of the created deposit
     */
    function depositCollateral(
        uint256 loanId,
        address tokenAddress,
        uint256 amount
    ) external nonReentrant returns (uint256 depositId) {
        if (!supportedTokens[tokenAddress].isSupported) {
            revert CollateralManager__TokenNotSupported();
        }
        if (amount == 0) revert CollateralManager__InvalidAmount();

        TokenInfo storage tokenInfo = supportedTokens[tokenAddress];

        // Check max deposit
        if (amount > tokenInfo.maxDepositAmount) {
            revert CollateralManager__MaxDepositExceeded();
        }

        depositId = nextDepositId++;

        deposits[depositId] = CollateralDeposit({
            depositId: depositId,
            depositor: msg.sender,
            tokenAddress: tokenAddress,
            amount: amount,
            loanId: loanId,
            isLocked: false,
            depositTimestamp: block.timestamp,
            lockedTimestamp: 0
        });

        loanToDepositIds[loanId].push(depositId);
        userDepositIds[msg.sender].push(depositId);

        tokenInfo.totalDeposited += amount;

        // Transfer tokens from user to this contract
        IERC20(tokenAddress).safeTransferFrom(
            msg.sender,
            address(this),
            amount
        );

        emit CollateralDeposited(
            depositId,
            msg.sender,
            loanId,
            tokenAddress,
            amount,
            block.timestamp
        );

        return depositId;
    }

    /**
     * @notice Withdraw unlocked collateral
     * @param depositId The ID of the deposit to withdraw
     */
    function withdrawCollateral(uint256 depositId) external nonReentrant {
        CollateralDeposit storage deposit = deposits[depositId];

        if (deposit.depositor == address(0))
            revert CollateralManager__DepositNotFound();
        if (deposit.depositor != msg.sender)
            revert CollateralManager__UnauthorizedWithdrawal();
        if (deposit.isLocked) revert CollateralManager__DepositLocked();

        address token = deposit.tokenAddress;
        uint256 amount = deposit.amount;
        address depositor = deposit.depositor;

        // Update state
        supportedTokens[token].totalDeposited -= amount;
        delete deposits[depositId];

        // Transfer tokens back to user
        IERC20(token).safeTransfer(depositor, amount);

        emit CollateralWithdrawn(depositId, depositor, token, amount);
    }

    /**
     * @notice Lock collateral when loan becomes active (called by LendingPool)
     * @param depositId The ID of the deposit to lock
     * @param loanId The ID of the loan
     */
    function lockCollateral(
        uint256 depositId,
        uint256 loanId
    ) external onlyRole(LENDING_POOL_ROLE) nonReentrant {
        CollateralDeposit storage deposit = deposits[depositId];

        if (deposit.depositor == address(0))
            revert CollateralManager__DepositNotFound();
        if (deposit.isLocked) revert CollateralManager__DepositLocked();
        if (deposit.loanId != loanId) revert CollateralManager__InvalidAmount();

        deposit.isLocked = true;
        deposit.lockedTimestamp = block.timestamp;

        emit CollateralLocked(
            depositId,
            loanId,
            deposit.tokenAddress,
            deposit.amount,
            block.timestamp
        );
    }

    /**
     * @notice Unlock collateral after successful repayment (called by LendingPool)
     * @param depositId The ID of the deposit to unlock
     */
    function unlockCollateral(
        uint256 depositId
    ) external onlyRole(LENDING_POOL_ROLE) nonReentrant {
        CollateralDeposit storage deposit = deposits[depositId];

        if (deposit.depositor == address(0))
            revert CollateralManager__DepositNotFound();
        if (!deposit.isLocked) revert CollateralManager__DepositNotLocked();

        deposit.isLocked = false;

        emit CollateralUnlocked(
            depositId,
            deposit.loanId,
            deposit.tokenAddress,
            deposit.amount
        );
    }

    /**
     * @notice Liquidate collateral for a defaulted loan
     * @param loanId The ID of the defaulted loan
     * @param loanAmount The outstanding loan amount in USD (18 decimals)
     * @param lender The address of the lender to receive funds
     * @return recoveredAmount The amount recovered from liquidation in USD
     */
    function liquidateCollateral(
        uint256 loanId,
        uint256 loanAmount,
        address lender
    )
        external
        onlyRole(LENDING_POOL_ROLE)
        nonReentrant
        returns (uint256 recoveredAmount)
    {
        if (lender == address(0)) revert CollateralManager__ZeroAddress();

        uint256[] memory depositIds = loanToDepositIds[loanId];
        if (depositIds.length == 0)
            revert CollateralManager__InsufficientCollateral();

        uint256 totalRecovered = 0;

        for (uint256 i = 0; i < depositIds.length; i++) {
            CollateralDeposit storage deposit = deposits[depositIds[i]];

            if (!deposit.isLocked) continue;

            // Check grace period
            if (
                block.timestamp <
                deposit.lockedTimestamp + LIQUIDATION_GRACE_PERIOD
            ) {
                revert CollateralManager__GracePeriodActive();
            }

            // Get collateral value
            uint256 collateralValue = priceOracle.getTokenValueInUSD(
                deposit.tokenAddress,
                deposit.amount,
                tokenDecimals[deposit.tokenAddress]
            );

            // Apply liquidation penalty
            uint256 penalty = supportedTokens[deposit.tokenAddress]
                .liquidationPenalty;
            uint256 valueAfterPenalty = (collateralValue *
                (BASIS_POINTS - penalty)) / BASIS_POINTS;

            totalRecovered += valueAfterPenalty;

            // Transfer collateral to lender
            IERC20(deposit.tokenAddress).safeTransfer(lender, deposit.amount);

            // Update state
            supportedTokens[deposit.tokenAddress].totalDeposited -= deposit
                .amount;

            emit CollateralLiquidated(
                depositIds[i],
                loanId,
                deposit.depositor,
                lender,
                deposit.tokenAddress,
                deposit.amount,
                valueAfterPenalty
            );

            // Clear deposit
            delete deposits[depositIds[i]];
        }

        // Clear loan deposits
        delete loanToDepositIds[loanId];

        return totalRecovered;
    }

    /**
     * @notice Get the USD value of collateral for a loan
     * @param loanId The ID of the loan
     * @return valueInUSD The total collateral value in USD (18 decimals)
     */
    function getLoanCollateralValue(
        uint256 loanId
    ) external view returns (uint256 valueInUSD) {
        uint256[] memory depositIds = loanToDepositIds[loanId];
        uint256 totalValue = 0;

        for (uint256 i = 0; i < depositIds.length; i++) {
            CollateralDeposit memory deposit = deposits[depositIds[i]];

            if (deposit.amount > 0) {
                uint256 value = priceOracle.getTokenValueInUSD(
                    deposit.tokenAddress,
                    deposit.amount,
                    tokenDecimals[deposit.tokenAddress]
                );
                totalValue += value;
            }
        }

        return totalValue;
    }

    /**
     * @notice Get collateral deposit details
     * @param depositId The ID of the deposit
     * @return deposit The collateral deposit struct
     */
    function getCollateralDeposit(
        uint256 depositId
    ) external view returns (CollateralDeposit memory) {
        return deposits[depositId];
    }

    /**
     * @notice Get all collateral deposits for a loan
     * @param loanId The ID of the loan
     * @return loanDeposits Array of collateral deposits
     */
    function getLoanCollateral(
        uint256 loanId
    ) external view returns (CollateralDeposit[] memory) {
        uint256[] memory depositIds = loanToDepositIds[loanId];
        CollateralDeposit[] memory loanDeposits = new CollateralDeposit[](
            depositIds.length
        );

        for (uint256 i = 0; i < depositIds.length; i++) {
            loanDeposits[i] = deposits[depositIds[i]];
        }

        return loanDeposits;
    }

    /**
     * @notice Get all deposits for a user
     * @param user The user address
     * @return userDeposits Array of user's deposits
     */
    function getUserDeposits(
        address user
    ) external view returns (CollateralDeposit[] memory) {
        uint256[] memory depositIds = userDepositIds[user];
        CollateralDeposit[] memory userDeposits = new CollateralDeposit[](
            depositIds.length
        );

        for (uint256 i = 0; i < depositIds.length; i++) {
            userDeposits[i] = deposits[depositIds[i]];
        }

        return userDeposits;
    }

    /**
     * @notice Check if collateral is sufficient for a loan
     * @param loanId The ID of the loan
     * @param loanAmount The loan amount in USD (18 decimals)
     * @param requiredRatio The required collateral ratio (basis points)
     * @return isSufficient True if collateral is sufficient
     */
    function isCollateralSufficient(
        uint256 loanId,
        uint256 loanAmount,
        uint256 requiredRatio
    ) external view returns (bool) {
        if (loanAmount == 0) return true;

        uint256 collateralValue = this.getLoanCollateralValue(loanId);
        uint256 actualRatio = (collateralValue * BASIS_POINTS) / loanAmount;

        return actualRatio >= requiredRatio;
    }

    /**
     * @notice Calculate health factor for a loan
     * @param loanId The ID of the loan
     * @param loanAmount The loan amount in USD (18 decimals)
     * @return healthFactor The health factor (10000 = 100%)
     */
    function calculateHealthFactor(
        uint256 loanId,
        uint256 loanAmount
    ) external view returns (uint256 healthFactor) {
        if (loanAmount == 0) return type(uint256).max;

        uint256 collateralValue = this.getLoanCollateralValue(loanId);
        healthFactor = (collateralValue * BASIS_POINTS) / loanAmount;

        return healthFactor;
    }

    /**
     * @notice Check if a loan is eligible for liquidation
     * @param loanId The ID of the loan
     * @param loanAmount The loan amount in USD (18 decimals)
     * @return canLiquidate True if loan can be liquidated
     */
    function canLiquidate(
        uint256 loanId,
        uint256 loanAmount
    ) external view returns (bool) {
        if (loanAmount == 0) return false;

        uint256 healthFactor = this.calculateHealthFactor(loanId, loanAmount);

        // Can liquidate if health factor below threshold (110%)
        return healthFactor < LIQUIDATION_THRESHOLD;
    }

    /**
     * @notice Get all supported collateral tokens
     * @return tokens Array of supported token addresses
     */
    function getSupportedTokens() external view returns (address[] memory) {
        return supportedTokenList;
    }

    /**
     * @notice Get token information
     * @param token The token address
     * @return tokenInfo The token info struct
     */
    function getTokenInfo(
        address token
    ) external view returns (TokenInfo memory) {
        return supportedTokens[token];
    }

    /**
     * @notice Get detailed collateral value information
     * @param token The token address
     * @param amount The token amount
     * @return collateralValue Struct with value details
     */
    function getCollateralValueDetails(
        address token,
        uint256 amount
    ) external view returns (CollateralValue memory) {
        uint256 valueInUSD = priceOracle.getTokenValueInUSD(
            token,
            amount,
            tokenDecimals[token]
        );

        return
            CollateralValue({
                tokenAddress: token,
                amount: amount,
                valueInUSD: valueInUSD,
                lastUpdated: block.timestamp
            });
    }
}

contracts/interfaces/LendingPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "./ReputationManager.sol";
import "./CollateralManager.sol";
import "./LoanLogic.sol";
import "./ActiveOfferLib.sol";

/**
 * @title LendingPool
 * @notice Core P2P lending pool with reputation-based matching
 * @dev Integrates with ReputationManager and CollateralManager
 */
contract LendingPool is AccessControl, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ============ State Variables ============

    ReputationManager public immutable reputationManager;
    CollateralManager public immutable collateralManager;

    // Counters
    uint256 public nextOfferId = 1;
    uint256 public nextLoanId = 1;

    // Storage
    mapping(uint256 => LoanOffer) public loanOffers;
    mapping(uint256 => Loan) public loans;
    mapping(address => uint256[]) public userOffers;
    mapping(address => uint256[]) public userLoans;

    // Active offers lists
    uint256[] public activeLenderOffers;
    uint256[] public activeBorrowerRequests;

    // Platform fee (in basis points)
    uint256 public platformFeeRate = 100; // 1%
    uint256 public constant BASIS_POINTS = 10000;
    uint256 public constant MAX_PLATFORM_FEE = 500; // 5% max

    // Loan constraints
    uint256 public constant MIN_LOAN_DURATION = 1 days;
    uint256 public constant MAX_LOAN_DURATION = 365 days;
    uint256 public constant MAX_INTEREST_RATE = 5000; // 50%

    address public feeCollector;

    // ============ Enums ============

    enum LoanStatus {
        PENDING,
        ACTIVE,
        REPAID,
        DEFAULTED,
        CANCELLED
    }

    enum LoanType {
        LENDER_OFFER,
        BORROW_REQUEST
    }

    // ============ Structs ============

    struct LoanTerms {
        address tokenAddress;
        uint256 principalAmount;
        uint256 collateralAmount;
        address collateralToken;
        uint256 interestRate;
        uint256 duration;
        uint256 minReputation;
        uint256 collateralRatio;
    }

    struct LoanOffer {
        uint256 offerId;
        LoanType offerType;
        address creator;
        LoanTerms terms;
        bool isActive;
        uint256 createdAt;
    }

    struct Loan {
        uint256 loanId;
        LoanType loanType;
        address lender;
        address borrower;
        LoanTerms terms;
        LoanStatus status;
        uint256 startTime;
        uint256 dueTime;
        uint256 amountRepaid;
        uint256 collateralDepositId;
        bool hasCoSigner;
        address coSigner;
    }

    // ============ Events ============

    event LoanOfferCreated(
        uint256 indexed offerId,
        address indexed creator,
        LoanType offerType,
        uint256 principalAmount,
        uint256 interestRate,
        uint256 duration
    );

    event LoanOfferCancelled(uint256 indexed offerId, address indexed creator);

    event LoanMatched(
        uint256 indexed loanId,
        uint256 indexed offerId,
        address indexed lender,
        address borrower,
        uint256 principalAmount
    );

    event LoanRepayment(
        uint256 indexed loanId,
        address indexed borrower,
        uint256 amount,
        uint256 remainingAmount
    );

    event LoanRepaid(
        uint256 indexed loanId,
        address indexed borrower,
        uint256 totalRepaid
    );

    event LoanDefaulted(
        uint256 indexed loanId,
        address indexed borrower,
        uint256 unpaidAmount
    );

    event CollateralLiquidated(
        uint256 indexed loanId,
        address indexed borrower,
        uint256 recoveredAmount
    );

    event PlatformFeeCollected(uint256 indexed loanId, uint256 feeAmount);

    event PlatformFeeRateUpdated(uint256 oldRate, uint256 newRate);

    // ============ Errors ============

    error LendingPool__InvalidAmount();
    error LendingPool__InvalidDuration();
    error LendingPool__InvalidInterestRate();
    error LendingPool__InvalidCollateralRatio();
    error LendingPool__OfferNotFound();
    error LendingPool__OfferNotActive();
    error LendingPool__UnauthorizedCancellation();
    error LendingPool__InsufficientReputation();
    error LendingPool__InsufficientCollateral();
    error LendingPool__LoanNotActive();
    error LendingPool__LoanNotOverdue();
    error LendingPool__InvalidRepaymentAmount();
    error LendingPool__ZeroAddress();
    error LendingPool__TransferFailed();
    error LendingPool__InvalidFeeRate();

    // ============ Constructor ============

    constructor(
        address _reputationManager,
        address _collateralManager,
        address _feeCollector
    ) {
        if (
            _reputationManager == address(0) ||
            _collateralManager == address(0) ||
            _feeCollector == address(0)
        ) {
            revert LendingPool__ZeroAddress();
        }

        reputationManager = ReputationManager(_reputationManager);
        collateralManager = CollateralManager(_collateralManager);
        feeCollector = _feeCollector;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    // ============ External Functions - Offer Management ============

    /**
     * @notice Create a new loan offer or borrow request
     * @param offerType Type of offer (LENDER_OFFER or BORROW_REQUEST)
     * @param terms The loan terms
     * @return offerId The ID of the created offer
     */
    function createLoanOffer(
        LoanType offerType,
        LoanTerms calldata terms
    ) external nonReentrant returns (uint256 offerId) {
        // Validate terms
        _validateLoanTerms(terms);

        offerId = nextOfferId++;

        loanOffers[offerId] = LoanOffer({
            offerId: offerId,
            offerType: offerType,
            creator: msg.sender,
            terms: terms,
            isActive: true,
            createdAt: block.timestamp
        });

        userOffers[msg.sender].push(offerId);

        // Add to appropriate active list
        if (offerType == LoanType.LENDER_OFFER) {
            activeLenderOffers.push(offerId);

            // Lender must lock funds
            IERC20(terms.tokenAddress).safeTransferFrom(
                msg.sender,
                address(this),
                terms.principalAmount
            );
        } else {
            activeBorrowerRequests.push(offerId);
        }

        emit LoanOfferCreated(
            offerId,
            msg.sender,
            offerType,
            terms.principalAmount,
            terms.interestRate,
            terms.duration
        );

        return offerId;
    }

    /**
     * @notice Cancel an active loan offer
     * @param offerId The ID of the offer to cancel
     */
    function cancelLoanOffer(uint256 offerId) external nonReentrant {
        LoanOffer storage offer = loanOffers[offerId];

        if (offer.creator == address(0)) revert LendingPool__OfferNotFound();
        if (!offer.isActive) revert LendingPool__OfferNotActive();
        if (offer.creator != msg.sender)
            revert LendingPool__UnauthorizedCancellation();

        offer.isActive = false;

        // Remove from active lists
        if (offer.offerType == LoanType.LENDER_OFFER) {
            ActiveOfferLib.remove(activeLenderOffers, offerId);
        } else {
            ActiveOfferLib.remove(activeBorrowerRequests, offerId);
        }

        // Return funds if lender offer
        if (offer.offerType == LoanType.LENDER_OFFER) {
            IERC20(offer.terms.tokenAddress).safeTransfer(
                msg.sender,
                offer.terms.principalAmount
            );
        }

        emit LoanOfferCancelled(offerId, msg.sender);
    }

    /**
     * @notice Accept a loan offer and create an active loan
     * @param offerId The ID of the offer to accept
     * @param collateralDepositId The ID of the collateral deposit (for borrowers)
     * @return loanId The ID of the created loan
     */
    function acceptLoanOffer(
        uint256 offerId,
        uint256 collateralDepositId
    ) external nonReentrant returns (uint256 loanId) {
        LoanOffer storage offer = loanOffers[offerId];

        if (offer.creator == address(0)) revert LendingPool__OfferNotFound();
        if (!offer.isActive) revert LendingPool__OfferNotActive();

        address lender;
        address borrower;

        if (offer.offerType == LoanType.LENDER_OFFER) {
            // Lender created offer, msg.sender is borrower
            lender = offer.creator;
            borrower = msg.sender;

            // Check borrower's reputation
            if (
                !reputationManager.meetsReputationRequirement(
                    borrower,
                    offer.terms.minReputation
                )
            ) {
                revert LendingPool__InsufficientReputation();
            }
        } else {
            // Borrower created request, msg.sender is lender
            lender = msg.sender;
            borrower = offer.creator;

            // Lender must provide funds
            IERC20(offer.terms.tokenAddress).safeTransferFrom(
                lender,
                address(this),
                offer.terms.principalAmount
            );
        }

        // Verify and lock collateral
        if (offer.terms.collateralAmount > 0) {
            bool sufficient = collateralManager.isCollateralSufficient(
                collateralDepositId,
                offer.terms.principalAmount,
                offer.terms.collateralRatio
            );

            if (!sufficient) revert LendingPool__InsufficientCollateral();

            collateralManager.lockCollateral(collateralDepositId, nextLoanId);
        }

        // Create loan
        loanId = nextLoanId++;

        loans[loanId] = Loan({
            loanId: loanId,
            loanType: offer.offerType,
            lender: lender,
            borrower: borrower,
            terms: offer.terms,
            status: LoanStatus.ACTIVE,
            startTime: block.timestamp,
            dueTime: block.timestamp + offer.terms.duration,
            amountRepaid: 0,
            collateralDepositId: collateralDepositId,
            hasCoSigner: false,
            coSigner: address(0)
        });

        userLoans[lender].push(loanId);
        userLoans[borrower].push(loanId);

        // Deactivate offer
        offer.isActive = false;
        if (offer.offerType == LoanType.LENDER_OFFER) {
            ActiveOfferLib.remove(activeLenderOffers, offerId);
        } else {
            ActiveOfferLib.remove(activeBorrowerRequests, offerId);
        }

        // Transfer principal to borrower (minus platform fee)
        uint256 platformFee = (offer.terms.principalAmount * platformFeeRate) /
            BASIS_POINTS;
        uint256 amountToBorrower = offer.terms.principalAmount - platformFee;

        IERC20(offer.terms.tokenAddress).safeTransfer(
            borrower,
            amountToBorrower
        );

        if (platformFee > 0) {
            IERC20(offer.terms.tokenAddress).safeTransfer(
                feeCollector,
                platformFee
            );
            emit PlatformFeeCollected(loanId, platformFee);
        }

        emit LoanMatched(
            loanId,
            offerId,
            lender,
            borrower,
            offer.terms.principalAmount
        );

        return loanId;
    }

    // ============ External Functions - Loan Management ============

    /**
     * @notice Repay an active loan (partial or full)
     * @param loanId The ID of the loan
     * @param amount The amount to repay
     */
    function repayLoan(uint256 loanId, uint256 amount) external nonReentrant {
        Loan storage loan = loans[loanId];

        if (loan.status != LoanStatus.ACTIVE)
            revert LendingPool__LoanNotActive();
        if (amount == 0) revert LendingPool__InvalidRepaymentAmount();

        uint256 amountDue = LoanLogic.calculateAmountDue(
            loan.terms.principalAmount,
            loan.terms.interestRate
        );
        uint256 remainingAmount = amountDue - loan.amountRepaid;

        if (amount > remainingAmount) {
            amount = remainingAmount;
        }

        loan.amountRepaid += amount;

        // Transfer repayment from borrower to lender
        IERC20(loan.terms.tokenAddress).safeTransferFrom(
            msg.sender,
            loan.lender,
            amount
        );

        emit LoanRepayment(
            loanId,
            loan.borrower,
            amount,
            remainingAmount - amount
        );

        // Check if fully repaid
        if (loan.amountRepaid >= amountDue) {
            _completeLoanRepayment(loanId);
        }
    }

    /**
     * @notice Liquidate a defaulted loan
     * @param loanId The ID of the loan
     */
    function liquidateLoan(uint256 loanId) external nonReentrant {
        Loan storage loan = loans[loanId];

        if (loan.status != LoanStatus.ACTIVE)
            revert LendingPool__LoanNotActive();
        if (block.timestamp <= loan.dueTime)
            revert LendingPool__LoanNotOverdue();

        uint256 amountDue = LoanLogic.calculateAmountDue(
            loan.terms.principalAmount,
            loan.terms.interestRate
        );
        uint256 unpaidAmount = amountDue - loan.amountRepaid;

        // Liquidate collateral
        uint256 recoveredAmount = 0;
        if (loan.terms.collateralAmount > 0) {
            recoveredAmount = collateralManager.liquidateCollateral(
                loanId,
                unpaidAmount,
                loan.lender
            );
        }

        loan.status = LoanStatus.DEFAULTED;

        // Apply reputation penalties
        reputationManager.recordDefault(
            loan.borrower,
            loan.terms.principalAmount
        );

        // Penalize co-signer if exists
        if (loan.hasCoSigner) {
            reputationManager.penalizeCoSigner(
                loan.coSigner,
                loan.borrower,
                loan.terms.principalAmount
            );
        }

        emit LoanDefaulted(loanId, loan.borrower, unpaidAmount);
        emit CollateralLiquidated(loanId, loan.borrower, recoveredAmount);
    }

    // ============ View Functions ============

    /**
     * @notice Calculate total amount due for a loan (principal + interest)
     * @param loanId The ID of the loan
     * @return The total amount due
     */
    /*
    function calculateAmountDue(uint256 loanId) public view returns (uint256) {
        Loan memory loan = loans[loanId];

        if (
            loan.status == LoanStatus.PENDING ||
            loan.status == LoanStatus.CANCELLED
        ) {
            return 0;
        }

        uint256 interest = (loan.terms.principalAmount *
            loan.terms.interestRate) / BASIS_POINTS;
        return loan.terms.principalAmount + interest;
    }
    */
    /**
     * @notice Check if a loan is past due
     * @param loanId The ID of the loan
     * @return true if loan is past due
     */
    function isLoanOverdue(uint256 loanId) external view returns (bool) {
        Loan memory loan = loans[loanId];

        if (loan.status != LoanStatus.ACTIVE) return false;

        return block.timestamp > loan.dueTime;
    }

    /**
     * @notice Get loan details
     * @param loanId The ID of the loan
     * @return Loan struct with all details
     */
    function getLoan(uint256 loanId) external view returns (Loan memory) {
        return loans[loanId];
    }

    /**
     * @notice Get loan offer details
     * @param offerId The ID of the offer
     * @return LoanOffer struct with all details
     */
    function getLoanOffer(
        uint256 offerId
    ) external view returns (LoanOffer memory) {
        return loanOffers[offerId];
    }

    function getActiveLenderOfferIds()
        external
        view
        returns (uint256[] memory)
    {
        return activeLenderOffers;
    }

    function getActiveBorrowerRequestIds()
        external
        view
        returns (uint256[] memory)
    {
        return activeBorrowerRequests;
    }

    /**
     * @notice Get all loans for a user (as lender or borrower)
     * @param user The address of the user
     * @return Array of loan IDs
     */
    function getUserLoans(
        address user
    ) external view returns (uint256[] memory) {
        return userLoans[user];
    }

    /**
     * @notice Get user's loan offers
     * @param user The address of the user
     * @return Array of offer IDs
     */
    function getUserOffers(
        address user
    ) external view returns (uint256[] memory) {
        return userOffers[user];
    }

    // ============ Admin Functions ============

    /**
     * @notice Update platform fee rate
     * @param newFeeRate New fee rate in basis points
     */
    function setPlatformFeeRate(
        uint256 newFeeRate
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (newFeeRate > MAX_PLATFORM_FEE) revert LendingPool__InvalidFeeRate();

        uint256 oldRate = platformFeeRate;
        platformFeeRate = newFeeRate;

        emit PlatformFeeRateUpdated(oldRate, newFeeRate);
    }

    /**
     * @notice Update fee collector address
     * @param newFeeCollector New fee collector address
     */
    function setFeeCollector(
        address newFeeCollector
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (newFeeCollector == address(0)) revert LendingPool__ZeroAddress();
        feeCollector = newFeeCollector;
    }

    // ============ Internal Functions ============

    /**
     * @notice Complete loan repayment and unlock collateral
     * @param loanId The ID of the loan
     */
    function _completeLoanRepayment(uint256 loanId) internal {
        Loan storage loan = loans[loanId];

        loan.status = LoanStatus.REPAID;

        // Unlock collateral
        if (loan.terms.collateralAmount > 0) {
            collateralManager.unlockCollateral(loan.collateralDepositId);
        }

        // Update reputation
        reputationManager.recordSuccessfulRepayment(
            loan.borrower,
            loan.terms.principalAmount
        );

        // Reward co-signer if exists
        if (loan.hasCoSigner) {
            reputationManager.rewardCoSigner(loan.coSigner, loan.borrower);
        }

        emit LoanRepaid(loanId, loan.borrower, loan.amountRepaid);
    }

    /**
     * @notice Validate loan terms
     * @param terms The loan terms to validate
     */
    function _validateLoanTerms(LoanTerms calldata terms) internal pure {
        if (terms.principalAmount == 0) revert LendingPool__InvalidAmount();
        if (
            terms.duration < MIN_LOAN_DURATION ||
            terms.duration > MAX_LOAN_DURATION
        ) {
            revert LendingPool__InvalidDuration();
        }
        if (terms.interestRate > MAX_INTEREST_RATE) {
            revert LendingPool__InvalidInterestRate();
        }
        if (terms.collateralRatio > 0 && terms.collateralRatio < 10000) {
            revert LendingPool__InvalidCollateralRatio();
        }
    }

    /**
     * @notice Remove offer from active list
     * @param offerId The offer ID to remove
     * @param offerType The type of offer
     */
    function _removeFromActiveList(
        uint256 offerId,
        LoanType offerType
    ) internal {
        uint256[] storage activeList = offerType == LoanType.LENDER_OFFER
            ? activeLenderOffers
            : activeBorrowerRequests;

        for (uint256 i = 0; i < activeList.length; i++) {
            if (activeList[i] == offerId) {
                activeList[i] = activeList[activeList.length - 1];
                activeList.pop();
                break;
            }
        }
    }
}

contracts/interfaces/LendingPoolLens.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./LendingPool.sol";

contract LendingPoolLens {
    LendingPool public immutable pool;

    constructor(address lendingPool) {
        require(lendingPool != address(0), "ZERO_ADDRESS");
        pool = LendingPool(lendingPool);
    }

    // ============ ACTIVE OFFERS ============

    function getActiveLenderOffers() external view returns (uint256[] memory) {
        uint256[] memory offerIds = pool.getActiveLenderOfferIds();
        return _filterActiveOffers(offerIds);
    }

    function getActiveBorrowerRequests()
        external
        view
        returns (uint256[] memory)
    {
        uint256[] memory offerIds = pool.getActiveBorrowerRequestIds();
        return _filterActiveOffers(offerIds);
    }

    function _filterActiveOffers(
        uint256[] memory offerIds
    ) internal view returns (uint256[] memory) {
        uint256 count = 0;

        for (uint256 i = 0; i < offerIds.length; i++) {
            (, , , , bool isActive, ) = pool.loanOffers(offerIds[i]);
            if (isActive) {
                count++;
            }
        }

        uint256[] memory activeOffers = new uint256[](count);
        uint256 index = 0;

        for (uint256 i = 0; i < offerIds.length; i++) {
            (, , , , bool isActive, ) = pool.loanOffers(offerIds[i]);
            if (isActive) {
                activeOffers[index] = offerIds[i];
                index++;
            }
        }

        return activeOffers;
    }

    // ============ USER LOANS ============

    function getUserLoans(
        address user
    ) external view returns (uint256[] memory) {
        return pool.getUserLoans(user);
    }

    function getUserActiveLoans(
        address user
    ) external view returns (LendingPool.Loan[] memory) {
        uint256[] memory loanIds = pool.getUserLoans(user);
        uint256 activeCount = 0;

        for (uint256 i = 0; i < loanIds.length; i++) {
            LendingPool.Loan memory loan = pool.getLoan(loanIds[i]);
            if (loan.status == LendingPool.LoanStatus.ACTIVE) {
                activeCount++;
            }
        }

        LendingPool.Loan[] memory activeLoans = new LendingPool.Loan[](
            activeCount
        );

        uint256 index = 0;
        for (uint256 i = 0; i < loanIds.length; i++) {
            LendingPool.Loan memory loan = pool.getLoan(loanIds[i]);
            if (loan.status == LendingPool.LoanStatus.ACTIVE) {
                activeLoans[index] = loan;
                index++;
            }
        }

        return activeLoans;
    }

    // ============ HELPERS ============

    function getLoanAmountDue(uint256 loanId) external view returns (uint256) {
        LendingPool.Loan memory loan = pool.getLoan(loanId);

        if (
            loan.status == LendingPool.LoanStatus.PENDING ||
            loan.status == LendingPool.LoanStatus.CANCELLED
        ) {
            return 0;
        }

        return
            loan.terms.principalAmount +
            (loan.terms.principalAmount * loan.terms.interestRate) /
            pool.BASIS_POINTS();
    }

    function getPlatformStats()
        external
        view
        returns (
            uint256 totalLoans,
            uint256 totalOffers,
            uint256 activeLenderOffers,
            uint256 activeBorrowerRequests,
            uint256 platformFeeRate
        )
    {
        // Counters live in LendingPool
        totalLoans = pool.nextLoanId() - 1;
        totalOffers = pool.nextOfferId() - 1;

        // Active offers
        activeLenderOffers = pool.getActiveLenderOfferIds().length;
        activeBorrowerRequests = pool.getActiveBorrowerRequestIds().length;

        platformFeeRate = pool.platformFeeRate();
    }
}

contracts/interfaces/LoanLogic.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

library LoanLogic {
    uint256 internal constant BASIS_POINTS = 10000;

    function calculateAmountDue(
        uint256 principal,
        uint256 interestRate
    ) internal pure returns (uint256) {
        return principal + (principal * interestRate) / BASIS_POINTS;
    }
}

contracts/interfaces/PriceOracle.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@chainlink/contracts/src/v0.8/shared/interfaces/AggregatorV3Interface.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title PriceOracle
 * @notice Wrapper contract for Chainlink price feeds
 * @dev Provides unified interface for getting token prices in USD
 */
contract PriceOracle is Ownable {
    // ============ State Variables ============

    // Mapping from token address to Chainlink price feed
    mapping(address => AggregatorV3Interface) public priceFeeds;

    // Mapping to track supported tokens
    mapping(address => bool) public isSupportedToken;

    // Array of all supported tokens
    address[] public supportedTokens;

    // Stale price threshold (default: 1 hour)
    uint256 public stalePriceThreshold = 1 hours;

    // Price deviation threshold for additional validation (in basis points)
    // e.g., 5000 = 50% deviation allowed
    uint256 public constant MAX_PRICE_DEVIATION = 5000; // 50%

    // Decimals for USD price (standardized to 18 decimals)
    uint8 public constant PRICE_DECIMALS = 18;

    // ============ Structs ============

    struct PriceData {
        uint256 price; // Price in USD (18 decimals)
        uint256 timestamp; // When price was updated
        uint80 roundId; // Chainlink round ID
        bool isValid; // Whether price is valid
    }

    // ============ Events ============

    event PriceFeedUpdated(
        address indexed token,
        address indexed priceFeed,
        string tokenSymbol
    );

    event PriceFeedRemoved(address indexed token);

    event PriceRetrieved(
        address indexed token,
        uint256 price,
        uint256 timestamp
    );

    event StalePriceThresholdUpdated(
        uint256 oldThreshold,
        uint256 newThreshold
    );

    event PriceValidationFailed(address indexed token, string reason);

    // ============ Errors ============

    error PriceOracle__InvalidPriceFeed();
    error PriceOracle__PriceFeedNotSet();
    error PriceOracle__StalePrice(uint256 timeSinceUpdate);
    error PriceOracle__InvalidPrice();
    error PriceOracle__InvalidRoundData();
    error PriceOracle__TokenAlreadySupported();
    error PriceOracle__TokenNotSupported();
    error PriceOracle__InvalidThreshold();
    error PriceOracle__ZeroAddress();

    // ============ Constructor ============

    constructor() Ownable() {}

    // ============ External Functions ============

    /**
     * @notice Set or update price feed for a token
     * @param token The token address
     * @param priceFeed The Chainlink price feed address
     * @param tokenSymbol The token symbol (for events)
     */
    function setPriceFeed(
        address token,
        address priceFeed,
        string calldata tokenSymbol
    ) external onlyOwner {
        if (token == address(0)) revert PriceOracle__ZeroAddress();
        if (priceFeed == address(0)) revert PriceOracle__InvalidPriceFeed();

        // Validate price feed by attempting to get latest round data
        AggregatorV3Interface feed = AggregatorV3Interface(priceFeed);
        try feed.latestRoundData() returns (
            uint80,
            int256 answer,
            uint256,
            uint256,
            uint80
        ) {
            if (answer <= 0) revert PriceOracle__InvalidPrice();
        } catch {
            revert PriceOracle__InvalidPriceFeed();
        }

        // Add to supported tokens if new
        if (!isSupportedToken[token]) {
            supportedTokens.push(token);
            isSupportedToken[token] = true;
        }

        priceFeeds[token] = feed;
        emit PriceFeedUpdated(token, priceFeed, tokenSymbol);
    }

    /**
     * @notice Remove a price feed for a token
     * @param token The token address
     */
    function removePriceFeed(address token) external onlyOwner {
        if (!isSupportedToken[token]) revert PriceOracle__TokenNotSupported();

        delete priceFeeds[token];
        isSupportedToken[token] = false;

        // Remove from supported tokens array
        for (uint256 i = 0; i < supportedTokens.length; i++) {
            if (supportedTokens[i] == token) {
                supportedTokens[i] = supportedTokens[
                    supportedTokens.length - 1
                ];
                supportedTokens.pop();
                break;
            }
        }

        emit PriceFeedRemoved(token);
    }

    /**
     * @notice Get the latest price for a token in USD
     * @param token The token address
     * @return price The price in USD (18 decimals)
     */
    function getPrice(address token) external view returns (uint256) {
        PriceData memory priceData = _getPriceData(token);

        if (!priceData.isValid) {
            revert PriceOracle__InvalidPrice();
        }

        return priceData.price;
    }

    /**
     * @notice Get detailed price data for a token
     * @param token The token address
     * @return priceData Struct containing price, timestamp, and validity
     */
    function getPriceData(
        address token
    ) external view returns (PriceData memory) {
        return _getPriceData(token);
    }

    /**
     * @notice Get token value in USD
     * @param token The token address
     * @param amount The token amount (in token's native decimals)
     * @param tokenDecimals The token's decimal places
     * @return valueInUSD The value in USD (18 decimals)
     */
    function getTokenValueInUSD(
        address token,
        uint256 amount,
        uint8 tokenDecimals
    ) external view returns (uint256 valueInUSD) {
        uint256 price = this.getPrice(token);

        // Normalize token amount to 18 decimals, then multiply by price
        if (tokenDecimals <= 18) {
            uint256 normalizedAmount = amount * (10 ** (18 - tokenDecimals));
            valueInUSD = (normalizedAmount * price) / 1e18;
        } else {
            // If token has > 18 decimals (rare), scale down
            uint256 normalizedAmount = amount / (10 ** (tokenDecimals - 18));
            valueInUSD = (normalizedAmount * price) / 1e18;
        }

        return valueInUSD;
    }

    /**
     * @notice Get USD amount required for specific token amount
     * @param token The token address
     * @param usdAmount The USD amount desired (18 decimals)
     * @param tokenDecimals The token's decimal places
     * @return tokenAmount The token amount needed
     */
    function getTokenAmountForUSD(
        address token,
        uint256 usdAmount,
        uint8 tokenDecimals
    ) external view returns (uint256 tokenAmount) {
        uint256 price = this.getPrice(token);

        if (price == 0) revert PriceOracle__InvalidPrice();

        // Calculate token amount needed (in 18 decimals)
        uint256 tokenAmount18Decimals = (usdAmount * 1e18) / price;

        // Convert to token's native decimals
        if (tokenDecimals <= 18) {
            tokenAmount = tokenAmount18Decimals / (10 ** (18 - tokenDecimals));
        } else {
            tokenAmount = tokenAmount18Decimals * (10 ** (tokenDecimals - 18));
        }

        return tokenAmount;
    }

    /**
     * @notice Check if a price is stale
     * @param token The token address
     * @return isStale True if price is stale
     */
    function isPriceStale(address token) external view returns (bool) {
        if (!isSupportedToken[token]) return true;

        AggregatorV3Interface priceFeed = priceFeeds[token];

        try priceFeed.latestRoundData() returns (
            uint80,
            int256,
            uint256,
            uint256 updatedAt,
            uint80
        ) {
            return block.timestamp - updatedAt > stalePriceThreshold;
        } catch {
            return true;
        }
    }

    /**
     * @notice Get all supported tokens
     * @return Array of supported token addresses
     */
    function getSupportedTokens() external view returns (address[] memory) {
        return supportedTokens;
    }

    /**
     * @notice Get the number of supported tokens
     * @return count The count of supported tokens
     */
    function getSupportedTokenCount() external view returns (uint256) {
        return supportedTokens.length;
    }

    /**
     * @notice Update stale price threshold
     * @param newThreshold New threshold in seconds
     */
    function setStalePriceThreshold(uint256 newThreshold) external onlyOwner {
        if (newThreshold == 0 || newThreshold > 1 days) {
            revert PriceOracle__InvalidThreshold();
        }

        uint256 oldThreshold = stalePriceThreshold;
        stalePriceThreshold = newThreshold;

        emit StalePriceThresholdUpdated(oldThreshold, newThreshold);
    }

    /**
     * @notice Get price feed decimals for a token
     * @param token The token address
     * @return decimals The decimals of the price feed
     */
    function getPriceFeedDecimals(address token) external view returns (uint8) {
        if (!isSupportedToken[token]) revert PriceOracle__TokenNotSupported();

        AggregatorV3Interface priceFeed = priceFeeds[token];
        return priceFeed.decimals();
    }

    /**
     * @notice Get price feed description for a token
     * @param token The token address
     * @return description The description of the price feed
     */
    function getPriceFeedDescription(
        address token
    ) external view returns (string memory) {
        if (!isSupportedToken[token]) revert PriceOracle__TokenNotSupported();

        AggregatorV3Interface priceFeed = priceFeeds[token];
        return priceFeed.description();
    }

    // ============ Internal Functions ============

    /**
     * @notice Internal function to get price data with validation
     * @param token The token address
     * @return priceData Struct containing price information
     */
    function _getPriceData(
        address token
    ) internal view returns (PriceData memory priceData) {
        if (!isSupportedToken[token]) revert PriceOracle__TokenNotSupported();

        AggregatorV3Interface priceFeed = priceFeeds[token];
        if (address(priceFeed) == address(0))
            revert PriceOracle__PriceFeedNotSet();

        try priceFeed.latestRoundData() returns (
            uint80 roundId,
            int256 answer,
            uint256 startedAt,
            uint256 updatedAt,
            uint80 answeredInRound
        ) {
            // Validate round data
            if (answeredInRound < roundId) {
                priceData.isValid = false;
                return priceData;
            }

            // Check for stale price
            uint256 timeSinceUpdate = block.timestamp - updatedAt;
            if (timeSinceUpdate > stalePriceThreshold) {
                revert PriceOracle__StalePrice(timeSinceUpdate);
            }

            // Check for invalid price
            if (answer <= 0) {
                revert PriceOracle__InvalidPrice();
            }

            // Get price feed decimals and normalize to 18 decimals
            uint8 decimals = priceFeed.decimals();
            uint256 price;

            if (decimals < PRICE_DECIMALS) {
                price = uint256(answer) * (10 ** (PRICE_DECIMALS - decimals));
            } else if (decimals > PRICE_DECIMALS) {
                price = uint256(answer) / (10 ** (decimals - PRICE_DECIMALS));
            } else {
                price = uint256(answer);
            }

            priceData = PriceData({
                price: price,
                timestamp: updatedAt,
                roundId: roundId,
                isValid: true
            });
        } catch {
            revert PriceOracle__InvalidRoundData();
        }
    }

    /**
     * @notice Check if price feed is responsive
     * @param token The token address
     * @return isResponsive True if price feed is working
     */
    function _isPriceFeedResponsive(
        address token
    ) internal view returns (bool) {
        if (!isSupportedToken[token]) return false;

        AggregatorV3Interface priceFeed = priceFeeds[token];

        try priceFeed.latestRoundData() returns (
            uint80,
            int256 answer,
            uint256,
            uint256,
            uint80
        ) {
            return answer > 0;
        } catch {
            return false;
        }
    }
}

contracts/interfaces/ReputationManager.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title ReputationManager
 * @notice Manages user reputation scores for decentralized lending platform
 * @dev Implements multi-factor reputation system with decay, anti-gaming, and co-signing
 */
contract ReputationManager is AccessControl, ReentrancyGuard {
    // ============ State Variables ============

    bytes32 public constant LENDING_POOL_ROLE = keccak256("LENDING_POOL_ROLE");
    bytes32 public constant COSIGNING_ROLE = keccak256("COSIGNING_ROLE");
    bytes32 public constant VERIFIER_ROLE = keccak256("VERIFIER_ROLE");
    bytes32 public constant DATA_FEED_ROLE = keccak256("DATA_FEED_ROLE");

    // Reputation score bounds
    uint256 public constant MIN_REPUTATION = 0;
    uint256 public constant MAX_REPUTATION = 1000;
    uint256 public constant STARTING_REPUTATION = 100;

    // Reputation weights (out of 100 for percentage)
    uint256 public constant REPAYMENT_WEIGHT = 50; // 50% weight
    uint256 public constant TRANSACTION_WEIGHT = 25; // 25% weight
    uint256 public constant COSIGNING_WEIGHT = 15; // 15% weight
    uint256 public constant WALLET_AGE_WEIGHT = 10; // 10% weight

    // Decay parameters
    uint256 public constant DECAY_START_DAYS = 90; // Start decay after 90 days of inactivity
    uint256 public constant MAX_DECAY_PERCENTAGE = 50; // Max 50% reputation loss
    uint256 public constant DECAY_PERIOD_DAYS = 180; // Full decay over 180 days

    // Anti-gaming parameters
    uint256 public constant REPUTATION_CAP_PERIOD = 1 days;
    uint256 public constant MAX_REPUTATION_GAIN_PER_PERIOD = 50;
    uint256 public constant WALLET_AGE_CAP_DAYS = 365; // Wallet age contribution caps at 1 year
    uint256 public constant COSIGN_COOLDOWN = 30 days;
    uint256 public constant MAX_COSIGN_BONUS = 100;

    // Off-chain verification bonuses
    uint256 public constant EMAIL_VERIFICATION_BONUS = 30;
    uint256 public constant PHONE_VERIFICATION_BONUS = 70;

    // Repayment scoring
    uint256 public constant SUCCESSFUL_REPAYMENT_BASE = 20;
    uint256 public constant DEFAULT_PENALTY_BASE = 100;
    uint256 public constant COSIGNER_PENALTY_MULTIPLIER = 30; // 30% of borrower penalty

    // ============ Structs ============

    struct ReputationData {
        uint256 baseScore;
        uint256 totalTransactions;
        uint256 uniqueCounterparties;
        uint256 totalValueTransferred;
        uint256 successfulRepayments;
        uint256 totalRepaymentValue;
        uint256 defaults;
        uint256 totalDefaultValue;
        uint256 walletCreationTime;
        uint256 lastActivityTimestamp;
        uint256 lastReputationUpdate;
        bool emailVerified;
        bool phoneVerified;
        uint256 coSigningBonus;
        uint256 reputationGainedToday;
        uint256 lastDailyResetTimestamp;
    }

    struct CoSigningHistory {
        mapping(address => uint256) coSignCount; // borrower => count
        mapping(address => uint256) lastCoSignTime; // borrower => timestamp
        uint256 totalActiveCoSigns;
    }

    // ============ Storage ============

    mapping(address => ReputationData) private reputationData;
    mapping(address => CoSigningHistory) private coSigningHistory;
    mapping(address => mapping(address => bool)) private hasInteracted; // For unique counterparties

    // ============ Events ============

    event ReputationUpdated(
        address indexed user,
        uint256 oldScore,
        uint256 newScore,
        string reason
    );

    event OffChainVerification(
        address indexed user,
        string verificationType,
        uint256 bonusAdded
    );

    event ReputationDecay(
        address indexed user,
        uint256 decayAmount,
        uint256 daysSinceActivity
    );

    event ReputationPenalty(
        address indexed user,
        uint256 penaltyAmount,
        string reason
    );

    event OnChainMetricsUpdated(
        address indexed user,
        uint256 transactions,
        uint256 counterparties,
        uint256 totalValue
    );

    // ============ Errors ============

    error ReputationManager__Unauthorized();
    error ReputationManager__InvalidAddress();
    error ReputationManager__AlreadyVerified();
    error ReputationManager__ReputationCapReached();
    error ReputationManager__InvalidAmount();

    // ============ Constructor ============

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(VERIFIER_ROLE, msg.sender);
        _grantRole(DATA_FEED_ROLE, msg.sender);
    }

    // ============ External Functions ============

    /**
     * @notice Get the current reputation score for a user (with decay applied)
     * @param user The address of the user
     * @return The calculated reputation score
     */
    function getReputationScore(address user) external view returns (uint256) {
        return _calculateReputationScore(user);
    }

    /**
     * @notice Get detailed reputation data for a user
     * @param user The address of the user
     * @return ReputationData struct with all metrics
     */
    function getReputationData(
        address user
    ) external view returns (ReputationData memory) {
        return reputationData[user];
    }

    /**
     * @notice Initialize reputation for a new user
     * @param user The address of the user
     */
    function initializeReputation(
        address user
    ) external onlyRole(DATA_FEED_ROLE) {
        if (user == address(0)) revert ReputationManager__InvalidAddress();

        ReputationData storage data = reputationData[user];

        // Only initialize if not already initialized
        if (data.walletCreationTime == 0) {
            data.baseScore = STARTING_REPUTATION;
            data.walletCreationTime = block.timestamp;
            data.lastActivityTimestamp = block.timestamp;
            data.lastReputationUpdate = block.timestamp;
            data.lastDailyResetTimestamp = block.timestamp;

            emit ReputationUpdated(
                user,
                0,
                STARTING_REPUTATION,
                "Initial reputation"
            );
        }
    }

    /**
     * @notice Record successful loan repayment and update reputation
     * @param borrower The address of the borrower
     * @param loanAmount The amount repaid
     */
    function recordSuccessfulRepayment(
        address borrower,
        uint256 loanAmount
    ) external onlyRole(LENDING_POOL_ROLE) nonReentrant {
        if (borrower == address(0)) revert ReputationManager__InvalidAddress();
        if (loanAmount == 0) revert ReputationManager__InvalidAmount();

        _ensureInitialized(borrower);

        ReputationData storage data = reputationData[borrower];
        uint256 oldScore = _calculateReputationScore(borrower);

        // Update repayment history
        data.successfulRepayments++;
        data.totalRepaymentValue += loanAmount;
        data.lastActivityTimestamp = block.timestamp;

        // Calculate reputation bonus based on loan amount
        uint256 bonus = _calculateRepaymentBonus(loanAmount);

        // Check daily cap
        _checkAndResetDailyCap(borrower);
        if (
            data.reputationGainedToday + bonus > MAX_REPUTATION_GAIN_PER_PERIOD
        ) {
            bonus = MAX_REPUTATION_GAIN_PER_PERIOD - data.reputationGainedToday;
        }

        data.baseScore = _min(data.baseScore + bonus, MAX_REPUTATION);
        data.reputationGainedToday += bonus;

        uint256 newScore = _calculateReputationScore(borrower);
        emit ReputationUpdated(
            borrower,
            oldScore,
            newScore,
            "Successful repayment"
        );
    }

    /**
     * @notice Record loan default and apply penalty
     * @param borrower The address of the borrower who defaulted
     * @param loanAmount The amount of the defaulted loan
     */
    function recordDefault(
        address borrower,
        uint256 loanAmount
    ) external onlyRole(LENDING_POOL_ROLE) nonReentrant {
        if (borrower == address(0)) revert ReputationManager__InvalidAddress();
        if (loanAmount == 0) revert ReputationManager__InvalidAmount();

        _ensureInitialized(borrower);

        ReputationData storage data = reputationData[borrower];
        uint256 oldScore = _calculateReputationScore(borrower);

        // Update default history
        data.defaults++;
        data.totalDefaultValue += loanAmount;
        data.lastActivityTimestamp = block.timestamp;

        // Calculate penalty (severe)
        uint256 penalty = _calculateDefaultPenalty(
            loanAmount,
            data.totalRepaymentValue
        );

        // Apply penalty
        if (data.baseScore > penalty) {
            data.baseScore -= penalty;
        } else {
            data.baseScore = MIN_REPUTATION;
        }

        uint256 newScore = _calculateReputationScore(borrower);
        emit ReputationPenalty(borrower, penalty, "Loan default");
        emit ReputationUpdated(
            borrower,
            oldScore,
            newScore,
            "Default penalty applied"
        );
    }

    /**
     * @notice Record off-chain verification (email/phone)
     * @param user The address of the user
     * @param verificationType "email" or "phone"
     */
    function recordOffChainVerification(
        address user,
        string calldata verificationType
    ) external onlyRole(VERIFIER_ROLE) nonReentrant {
        if (user == address(0)) revert ReputationManager__InvalidAddress();

        _ensureInitialized(user);

        ReputationData storage data = reputationData[user];
        uint256 oldScore = _calculateReputationScore(user);
        uint256 bonus = 0;

        if (keccak256(bytes(verificationType)) == keccak256(bytes("email"))) {
            if (data.emailVerified) revert ReputationManager__AlreadyVerified();
            data.emailVerified = true;
            bonus = EMAIL_VERIFICATION_BONUS;
        } else if (
            keccak256(bytes(verificationType)) == keccak256(bytes("phone"))
        ) {
            if (data.phoneVerified) revert ReputationManager__AlreadyVerified();
            data.phoneVerified = true;
            bonus = PHONE_VERIFICATION_BONUS;
        }

        if (bonus > 0) {
            data.baseScore = _min(data.baseScore + bonus, MAX_REPUTATION);
            data.lastActivityTimestamp = block.timestamp;

            uint256 newScore = _calculateReputationScore(user);
            emit OffChainVerification(user, verificationType, bonus);
            emit ReputationUpdated(user, oldScore, newScore, verificationType);
        }
    }

    /**
     * @notice Add co-signing bonus to borrower's reputation
     * @param borrower The address of the borrower
     * @param coSigner The address of the co-signer
     * @param coSignerReputation The reputation of the co-signer
     * @return The bonus amount added
     */
    function addCoSigningBonus(
        address borrower,
        address coSigner,
        uint256 coSignerReputation
    ) external onlyRole(COSIGNING_ROLE) nonReentrant returns (uint256) {
        if (borrower == address(0) || coSigner == address(0)) {
            revert ReputationManager__InvalidAddress();
        }

        _ensureInitialized(borrower);
        _ensureInitialized(coSigner);

        uint256 oldScore = _calculateReputationScore(borrower);

        // Calculate bonus with diminishing returns
        uint256 bonus = _calculateCoSigningBonus(
            borrower,
            coSigner,
            coSignerReputation
        );

        if (bonus > 0) {
            ReputationData storage data = reputationData[borrower];

            // Check daily cap
            _checkAndResetDailyCap(borrower);
            if (
                data.reputationGainedToday + bonus >
                MAX_REPUTATION_GAIN_PER_PERIOD
            ) {
                bonus =
                    MAX_REPUTATION_GAIN_PER_PERIOD -
                    data.reputationGainedToday;
            }

            data.coSigningBonus = _min(
                data.coSigningBonus + bonus,
                MAX_COSIGN_BONUS
            );
            data.reputationGainedToday += bonus;
            data.lastActivityTimestamp = block.timestamp;

            // Update co-signing history
            CoSigningHistory storage history = coSigningHistory[coSigner];
            history.coSignCount[borrower]++;
            history.lastCoSignTime[borrower] = block.timestamp;
            history.totalActiveCoSigns++;

            uint256 newScore = _calculateReputationScore(borrower);
            emit ReputationUpdated(
                borrower,
                oldScore,
                newScore,
                "Co-signing bonus"
            );
        }

        return bonus;
    }

    /**
     * @notice Apply penalty to co-signer when borrower defaults
     * @param coSigner The address of the co-signer
     * @param borrower The address of the borrower who defaulted
     * @param loanAmount The amount of the defaulted loan
     */
    function penalizeCoSigner(
        address coSigner,
        address borrower,
        uint256 loanAmount
    ) external onlyRole(COSIGNING_ROLE) nonReentrant {
        if (coSigner == address(0) || borrower == address(0)) {
            revert ReputationManager__InvalidAddress();
        }

        _ensureInitialized(coSigner);

        ReputationData storage data = reputationData[coSigner];
        uint256 oldScore = _calculateReputationScore(coSigner);

        // Calculate penalty (30% of what borrower would get)
        uint256 borrowerPenalty = _calculateDefaultPenalty(loanAmount, 0);
        uint256 coSignerPenalty = (borrowerPenalty *
            COSIGNER_PENALTY_MULTIPLIER) / 100;

        // Apply penalty
        if (data.baseScore > coSignerPenalty) {
            data.baseScore -= coSignerPenalty;
        } else {
            data.baseScore = MIN_REPUTATION;
        }

        // Reduce co-signing bonus
        if (data.coSigningBonus > coSignerPenalty / 2) {
            data.coSigningBonus -= coSignerPenalty / 2;
        } else {
            data.coSigningBonus = 0;
        }

        data.lastActivityTimestamp = block.timestamp;

        // Update co-signing history
        CoSigningHistory storage history = coSigningHistory[coSigner];
        if (history.totalActiveCoSigns > 0) {
            history.totalActiveCoSigns--;
        }

        uint256 newScore = _calculateReputationScore(coSigner);
        emit ReputationPenalty(
            coSigner,
            coSignerPenalty,
            "Co-signed loan defaulted"
        );
        emit ReputationUpdated(
            coSigner,
            oldScore,
            newScore,
            "Co-signer penalty"
        );
    }

    /**
     * @notice Reward co-signer when borrower repays successfully
     * @param coSigner The address of the co-signer
     * @param borrower The address of the borrower
     */
    function rewardCoSigner(
        address coSigner,
        address borrower
    ) external onlyRole(COSIGNING_ROLE) nonReentrant {
        if (coSigner == address(0) || borrower == address(0)) {
            revert ReputationManager__InvalidAddress();
        }

        _ensureInitialized(coSigner);

        ReputationData storage data = reputationData[coSigner];
        uint256 oldScore = _calculateReputationScore(coSigner);

        // Small reward for successful co-signing
        uint256 reward = 10;

        // Check daily cap
        _checkAndResetDailyCap(coSigner);
        if (
            data.reputationGainedToday + reward > MAX_REPUTATION_GAIN_PER_PERIOD
        ) {
            reward =
                MAX_REPUTATION_GAIN_PER_PERIOD -
                data.reputationGainedToday;
        }

        data.baseScore = _min(data.baseScore + reward, MAX_REPUTATION);
        data.reputationGainedToday += reward;
        data.lastActivityTimestamp = block.timestamp;

        // Update co-signing history
        CoSigningHistory storage history = coSigningHistory[coSigner];
        if (history.totalActiveCoSigns > 0) {
            history.totalActiveCoSigns--;
        }

        uint256 newScore = _calculateReputationScore(coSigner);
        emit ReputationUpdated(
            coSigner,
            oldScore,
            newScore,
            "Co-signing reward"
        );
    }

    /**
     * @notice Update on-chain transaction metrics for a user
     * @param user The address of the user
     * @param txCount Number of transactions
     * @param counterparty Address interacted with
     * @param txValue Value of transaction
     */
    function updateOnChainMetrics(
        address user,
        uint256 txCount,
        address counterparty,
        uint256 txValue
    ) external onlyRole(DATA_FEED_ROLE) {
        if (user == address(0)) revert ReputationManager__InvalidAddress();

        _ensureInitialized(user);

        ReputationData storage data = reputationData[user];

        // Update transaction count
        data.totalTransactions += txCount;

        // Update unique counterparties
        if (counterparty != address(0) && !hasInteracted[user][counterparty]) {
            hasInteracted[user][counterparty] = true;
            data.uniqueCounterparties++;
        }

        // Update total value (small transactions contribute less)
        if (txValue > 0.01 ether) {
            // Minimum threshold
            data.totalValueTransferred += txValue;
        }

        data.lastActivityTimestamp = block.timestamp;

        emit OnChainMetricsUpdated(
            user,
            data.totalTransactions,
            data.uniqueCounterparties,
            data.totalValueTransferred
        );
    }

    /**
     * @notice Check if a user meets minimum reputation requirement
     * @param user The address of the user
     * @param minimumReputation The minimum reputation required
     * @return true if user meets requirement
     */
    function meetsReputationRequirement(
        address user,
        uint256 minimumReputation
    ) external view returns (bool) {
        return _calculateReputationScore(user) >= minimumReputation;
    }

    /**
     * @notice Get co-signing count for a pair
     * @param coSigner The co-signer address
     * @param borrower The borrower address
     * @return The number of times co-signed
     */
    function getCoSignCount(
        address coSigner,
        address borrower
    ) external view returns (uint256) {
        return coSigningHistory[coSigner].coSignCount[borrower];
    }

    /**
     * @notice Check if diminishing returns apply
     * @param coSigner The co-signer address
     * @param borrower The borrower address
     * @return true if diminishing returns apply
     */
    function hasDiminishingReturns(
        address coSigner,
        address borrower
    ) external view returns (bool) {
        CoSigningHistory storage history = coSigningHistory[coSigner];

        // Check if in cooldown period
        if (
            block.timestamp < history.lastCoSignTime[borrower] + COSIGN_COOLDOWN
        ) {
            return history.coSignCount[borrower] > 0;
        }

        return false;
    }

    // ============ Internal Functions ============

    /**
     * @notice Calculate total reputation score with all factors
     * @param user The address of the user
     * @return The final reputation score
     */
    function _calculateReputationScore(
        address user
    ) internal view returns (uint256) {
        ReputationData storage data = reputationData[user];

        // If not initialized, return 0
        if (data.walletCreationTime == 0) {
            return 0;
        }

        // Start with base score
        uint256 score = data.baseScore;

        // Add co-signing bonus
        score += data.coSigningBonus;

        // Calculate component scores
        uint256 repaymentScore = _calculateRepaymentScore(data);
        uint256 transactionScore = _calculateTransactionScore(data);
        uint256 walletAgeScore = _calculateWalletAgeScore(data);

        // Apply weights
        uint256 weightedScore = (repaymentScore *
            REPAYMENT_WEIGHT +
            transactionScore *
            TRANSACTION_WEIGHT +
            data.coSigningBonus *
            COSIGNING_WEIGHT +
            walletAgeScore *
            WALLET_AGE_WEIGHT) / 100;

        // Combine with base score
        score = (score + weightedScore) / 2;

        // Apply decay
        uint256 decayAmount = _calculateDecay(data);
        if (score > decayAmount) {
            score -= decayAmount;
        } else {
            score = MIN_REPUTATION;
        }

        // Ensure within bounds
        return _min(score, MAX_REPUTATION);
    }

    /**
     * @notice Calculate repayment history score
     */
    function _calculateRepaymentScore(
        ReputationData storage data
    ) internal view returns (uint256) {
        if (data.successfulRepayments == 0 && data.defaults == 0) {
            return STARTING_REPUTATION;
        }

        // Base calculation: successful repayments contribute positively
        uint256 successScore = data.successfulRepayments * 30;

        // Defaults severely hurt score
        uint256 defaultPenalty = data.defaults * 80;

        // Factor in loan amounts
        uint256 valueScore = 0;
        if (data.totalRepaymentValue > 0) {
            valueScore = _min((data.totalRepaymentValue / 1 ether) * 5, 100);
        }

        uint256 totalScore = successScore + valueScore;

        if (totalScore > defaultPenalty) {
            return _min(totalScore - defaultPenalty, 300);
        }

        return 0;
    }

    /**
     * @notice Calculate transaction activity score
     */
    function _calculateTransactionScore(
        ReputationData storage data
    ) internal view returns (uint256) {
        // Transaction count (capped to prevent spam)
        uint256 txScore = _min(data.totalTransactions * 2, 100);

        // Unique counterparties (diversity bonus)
        uint256 diversityScore = _min(data.uniqueCounterparties * 5, 100);

        // Total value transferred (meaningful activity)
        uint256 valueScore = 0;
        if (data.totalValueTransferred > 0) {
            valueScore = _min((data.totalValueTransferred / 1 ether) * 3, 100);
        }

        return _min(((txScore + diversityScore + valueScore) * 2) / 3, 200);
    }

    /**
     * @notice Calculate wallet age score
     */
    function _calculateWalletAgeScore(
        ReputationData storage data
    ) internal view returns (uint256) {
        uint256 ageDays = (block.timestamp - data.walletCreationTime) / 1 days;

        // Cap at 1 year
        ageDays = _min(ageDays, WALLET_AGE_CAP_DAYS);

        // Linear increase up to cap
        return (ageDays * 100) / WALLET_AGE_CAP_DAYS;
    }

    /**
     * @notice Calculate reputation decay based on inactivity
     */
    function _calculateDecay(
        ReputationData storage data
    ) internal view returns (uint256) {
        uint256 daysSinceActivity = (block.timestamp -
            data.lastActivityTimestamp) / 1 days;

        if (daysSinceActivity < DECAY_START_DAYS) {
            return 0;
        }

        uint256 decayDays = daysSinceActivity - DECAY_START_DAYS;

        if (decayDays >= DECAY_PERIOD_DAYS) {
            // Max decay reached
            return (data.baseScore * MAX_DECAY_PERCENTAGE) / 100;
        }

        // Linear decay over period
        uint256 decayPercentage = (decayDays * MAX_DECAY_PERCENTAGE) /
            DECAY_PERIOD_DAYS;
        return (data.baseScore * decayPercentage) / 100;
    }

    /**
     * @notice Calculate repayment bonus
     */
    function _calculateRepaymentBonus(
        uint256 loanAmount
    ) internal pure returns (uint256) {
        // Base bonus + amount-based bonus (capped)
        uint256 amountBonus = _min((loanAmount / 1 ether) * 2, 30);
        return SUCCESSFUL_REPAYMENT_BASE + amountBonus;
    }

    /**
     * @notice Calculate default penalty
     */
    function _calculateDefaultPenalty(
        uint256 loanAmount,
        uint256 totalRepaymentValue
    ) internal pure returns (uint256) {
        // Severe base penalty
        uint256 basePenalty = DEFAULT_PENALTY_BASE;

        // Additional penalty based on loan size
        uint256 amountPenalty = _min((loanAmount / 1 ether) * 10, 100);

        // Less penalty if user has good history
        uint256 historyReduction = 0;
        if (totalRepaymentValue > loanAmount * 10) {
            historyReduction = 20;
        }

        uint256 totalPenalty = basePenalty + amountPenalty;

        if (totalPenalty > historyReduction) {
            return totalPenalty - historyReduction;
        }

        return basePenalty;
    }

    /**
     * @notice Calculate co-signing bonus with diminishing returns
     */
    function _calculateCoSigningBonus(
        address borrower,
        address coSigner,
        uint256 coSignerReputation
    ) internal view returns (uint256) {
        CoSigningHistory storage history = coSigningHistory[coSigner];

        // Base bonus is proportional to co-signer's reputation
        uint256 baseBonus = (coSignerReputation * 10) / 100; // 10% of co-signer reputation
        baseBonus = _min(baseBonus, 50); // Cap at 50

        // Check if in cooldown period
        if (
            block.timestamp < history.lastCoSignTime[borrower] + COSIGN_COOLDOWN
        ) {
            // Apply diminishing returns based on count
            uint256 count = history.coSignCount[borrower];

            if (count == 0) {
                return baseBonus; // First time: full bonus
            } else if (count == 1) {
                return (baseBonus * 60) / 100; // Second time: 60%
            } else if (count == 2) {
                return (baseBonus * 30) / 100; // Third time: 30%
            } else {
                return (baseBonus * 10) / 100; // After that: 10%
            }
        }

        // Cooldown passed, reset to full bonus
        return baseBonus;
    }

    /**
     * @notice Ensure user is initialized
     */
    function _ensureInitialized(address user) internal {
        if (reputationData[user].walletCreationTime == 0) {
            reputationData[user].baseScore = STARTING_REPUTATION;
            reputationData[user].walletCreationTime = block.timestamp;
            reputationData[user].lastActivityTimestamp = block.timestamp;
            reputationData[user].lastReputationUpdate = block.timestamp;
            reputationData[user].lastDailyResetTimestamp = block.timestamp;
        }
    }

    /**
     * @notice Check and reset daily reputation gain cap
     */
    function _checkAndResetDailyCap(address user) internal {
        ReputationData storage data = reputationData[user];

        if (block.timestamp >= data.lastDailyResetTimestamp + 1 days) {
            data.reputationGainedToday = 0;
            data.lastDailyResetTimestamp = block.timestamp;
        }
    }

    /**
     * @notice Helper function to get minimum of two numbers
     */
    function _min(uint256 a, uint256 b) internal pure returns (uint256) {
        return a < b ? a : b;
    }
}

